-- KHUNYUI DATABASE 001 — SCHEMA + SECURITY BASE\n-- Run in Supabase SQL Editor on a new project.\n\nbegin;\n\ncreate extension if not exists pgcrypto;\n\ncreate table if not exists public.stores (\n  id uuid primary key default gen_random_uuid(),\n  slug text not null unique,\n  store_name text not null,\n  branch text not null,\n  timezone text not null default 'Asia/Bangkok',\n  accepting_orders boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.store_members (\n  store_id uuid not null references public.stores(id) on delete cascade,\n  user_id uuid not null references auth.users(id) on delete cascade,\n  role text not null default 'owner' check (role in ('owner','manager','staff')),\n  created_at timestamptz not null default now(),\n  primary key(store_id,user_id)\n);\n\ncreate table if not exists public.customer_access (\n  store_id uuid primary key references public.stores(id) on delete cascade,\n  home boolean not null default true,\n  somtam boolean not null default true,\n  yum boolean not null default true,\n  cart boolean not null default true,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.owner_preferences (\n  store_id uuid not null references public.stores(id) on delete cascade,\n  user_id uuid not null references auth.users(id) on delete cascade,\n  notify_new_orders boolean not null default true,\n  sound_new_orders boolean not null default true,\n  updated_at timestamptz not null default now(),\n  primary key(store_id,user_id)\n);\n\ncreate table if not exists public.menu_items (\n  id uuid primary key default gen_random_uuid(),\n  store_id uuid not null references public.stores(id) on delete cascade,\n  code text not null,\n  cat text not null check (cat in ('somtam','yum','side')),\n  subcategory text not null,\n  category text not null,\n  name text not null,\n  price numeric(12,2) not null check (price>=0),\n  description text,\n  image_url text,\n  legacy_image_path text,\n  is_available boolean not null default true,\n  sort_order integer not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique(store_id,code)\n);\ncreate index if not exists menu_items_store_sort_idx on public.menu_items(store_id,sort_order);\ncreate index if not exists menu_items_store_available_idx on public.menu_items(store_id,is_available);\n\ncreate table if not exists public.qr_points (\n  id uuid primary key default gen_random_uuid(),\n  store_id uuid not null references public.stores(id) on delete cascade,\n  token text not null unique,\n  label text not null default 'หน้าร้านหลัก',\n  fulfillment_type text not null default 'takeaway' check (fulfillment_type in ('dine_in','takeaway')),\n  table_label text,\n  active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index if not exists qr_points_store_idx on public.qr_points(store_id,active);\n\ncreate table if not exists public.order_counters (\n  store_id uuid not null references public.stores(id) on delete cascade,\n  order_date date not null,\n  last_value integer not null default 0 check (last_value>=0),\n  primary key(store_id,order_date)\n);\n\ncreate table if not exists public.orders (\n  id uuid primary key default gen_random_uuid(),\n  store_id uuid not null references public.stores(id) on delete restrict,\n  qr_point_id uuid references public.qr_points(id) on delete set null,\n  order_no text not null,\n  tracking_token text not null unique,\n  status text not null default 'new' check (status in ('new','preparing','ready','completed','cancelled')),\n  payment_method text not null default 'cash' check (payment_method in ('cash','qr')),\n  payment_status text not null default 'unpaid' check (payment_status in ('unpaid','pending','paid','failed','refunded')),\n  fulfillment_type text not null check (fulfillment_type in ('dine_in','takeaway')),\n  table_label text,\n  note text,\n  total numeric(12,2) not null default 0 check(total>=0),\n  item_count integer not null default 0 check(item_count>=0),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  payment_at timestamptz,\n  completed_at timestamptz,\n  unique(store_id,order_no,created_at)\n);\ncreate index if not exists orders_store_created_idx on public.orders(store_id,created_at desc);\ncreate index if not exists orders_store_status_idx on public.orders(store_id,status,created_at desc);\n\ncreate table if not exists public.order_items (\n  id uuid primary key default gen_random_uuid(),\n  order_id uuid not null references public.orders(id) on delete cascade,\n  store_id uuid not null references public.stores(id) on delete restrict,\n  menu_item_id uuid references public.menu_items(id) on delete set null,\n  menu_code text not null,\n  name text not null,\n  unit_price numeric(12,2) not null check(unit_price>=0),\n  quantity integer not null check(quantity between 1 and 99),\n  line_total numeric(12,2) not null check(line_total>=0),\n  note text,\n  modifiers jsonb not null default '[]'::jsonb,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists order_items_order_idx on public.order_items(order_id);\n\ncreate table if not exists public.order_events (\n  id bigserial primary key,\n  order_id uuid not null references public.orders(id) on delete cascade,\n  store_id uuid not null references public.stores(id) on delete cascade,\n  event_type text not null,\n  from_status text,\n  to_status text,\n  payload jsonb not null default '{}'::jsonb,\n  actor_user_id uuid references auth.users(id) on delete set null,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists order_events_order_idx on public.order_events(order_id,created_at);\n\ncreate or replace function public.touch_updated_at() returns trigger language plpgsql as $$\nbegin new.updated_at=now(); return new; end $$;\n\ndo $$ begin\n  create trigger stores_touch before update on public.stores for each row execute function public.touch_updated_at();\nexception when duplicate_object then null; end $$;\ndo $$ begin\n  create trigger customer_access_touch before update on public.customer_access for each row execute function public.touch_updated_at();\nexception when duplicate_object then null; end $$;\ndo $$ begin\n  create trigger owner_preferences_touch before update on public.owner_preferences for each row execute function public.touch_updated_at();\nexception when duplicate_object then null; end $$;\ndo $$ begin\n  create trigger menu_items_touch before update on public.menu_items for each row execute function public.touch_updated_at();\nexception when duplicate_object then null; end $$;\ndo $$ begin\n  create trigger qr_points_touch before update on public.qr_points for each row execute function public.touch_updated_at();\nexception when duplicate_object then null; end $$;\ndo $$ begin\n  create trigger orders_touch before update on public.orders for each row execute function public.touch_updated_at();\nexception when duplicate_object then null; end $$;\n\ncreate or replace function public.is_store_member(p_store_id uuid)\nreturns boolean language sql stable security definer set search_path=public,pg_temp as $$\n  select exists(select 1 from public.store_members sm where sm.store_id=p_store_id and sm.user_id=(select auth.uid()));\n$$;\n\n-- RLS: browser users cannot freely read/write other stores or orders.\nalter table public.stores enable row level security;\nalter table public.store_members enable row level security;\nalter table public.customer_access enable row level security;\nalter table public.owner_preferences enable row level security;\nalter table public.menu_items enable row level security;\nalter table public.qr_points enable row level security;\nalter table public.order_counters enable row level security;\nalter table public.orders enable row level security;\nalter table public.order_items enable row level security;\nalter table public.order_events enable row level security;\n\ndo $$ begin create policy stores_member_select on public.stores for select to authenticated using(public.is_store_member(id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy store_members_self_select on public.store_members for select to authenticated using(user_id=(select auth.uid())); exception when duplicate_object then null; end $$;\ndo $$ begin create policy customer_access_member_all on public.customer_access for all to authenticated using(public.is_store_member(store_id)) with check(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy owner_preferences_member_all on public.owner_preferences for all to authenticated using(public.is_store_member(store_id) and user_id=(select auth.uid())) with check(public.is_store_member(store_id) and user_id=(select auth.uid())); exception when duplicate_object then null; end $$;\ndo $$ begin create policy menu_items_member_select on public.menu_items for select to authenticated using(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy menu_items_member_update on public.menu_items for update to authenticated using(public.is_store_member(store_id)) with check(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy qr_points_member_all on public.qr_points for all to authenticated using(public.is_store_member(store_id)) with check(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy orders_member_select on public.orders for select to authenticated using(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy orders_member_update on public.orders for update to authenticated using(public.is_store_member(store_id)) with check(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy order_items_member_select on public.order_items for select to authenticated using(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\ndo $$ begin create policy order_events_member_select on public.order_events for select to authenticated using(public.is_store_member(store_id)); exception when duplicate_object then null; end $$;\n\nrevoke all on public.order_counters from anon,authenticated;\nrevoke all on public.orders from anon;\nrevoke all on public.order_items from anon;\nrevoke all on public.order_events from anon;\nrevoke all on public.menu_items from anon;\nrevoke all on public.qr_points from anon;\nrevoke all on public.customer_access from anon;\n\ngrant select,update on public.menu_items to authenticated;\ngrant select,update on public.orders to authenticated;\ngrant select on public.order_items,public.order_events,public.stores,public.store_members to authenticated;\ngrant select,insert,update,delete on public.qr_points to authenticated;\ngrant select,insert,update on public.customer_access,public.owner_preferences to authenticated;\n\ncommit;\n